messages.content:
In this JSON configuration, change only service.request_timeout_seconds from 30 to 45. Preserve every other key, value, list order, and value type. Return the whole valid JSON object without markdown or explanation.

{
  "service": {
    "name": "orders-api",
    "version": "3.2.1",
    "request_timeout_seconds": 30,
    "bind_address": "127.0.0.1",
    "port": 8080,
    "graceful_shutdown_seconds": 15,
    "max_request_bytes": 1048576
  },
  "database": {
    "engine": "postgresql",
    "host": "db.internal",
    "port": 5432,
    "name": "orders",
    "pool_min": 4,
    "pool_max": 24,
    "statement_timeout_seconds": 12,
    "ssl": true
  },
  "cache": {
    "engine": "redis",
    "host": "cache.internal",
    "port": 6379,
    "namespace": "orders:v3",
    "default_ttl_seconds": 300,
    "connect_timeout_seconds": 2
  },
  "workers": [
    {"name": "receipts", "concurrency": 4, "retry_limit": 3, "queue": "receipts"},
    {"name": "shipping", "concurrency": 2, "retry_limit": 5, "queue": "shipping"},
    {"name": "refunds", "concurrency": 2, "retry_limit": 2, "queue": "refunds"},
    {"name": "inventory", "concurrency": 6, "retry_limit": 4, "queue": "inventory"}
  ],
  "features": {
    "coupons": true,
    "express_shipping": true,
    "international_shipping": false,
    "guest_checkout": true,
    "automatic_refunds": false,
    "inventory_reservations": true
  },
  "logging": {
    "level": "INFO",
    "format": "json",
    "include_request_id": true,
    "redact_fields": ["authorization", "credit_card", "password"],
    "sample_rate": 1.0
  },
  "metrics": {
    "enabled": true,
    "endpoint": "/metrics",
    "histogram_buckets_ms": [5, 10, 25, 50, 100, 250, 500, 1000],
    "labels": {"environment": "staging", "region": "us-west-2"}
  },
  "security": {
    "allowed_origins": ["https://shop.example.com", "https://admin.example.com"],
    "csrf_enabled": true,
    "rate_limit_per_minute": 120,
    "trusted_proxy_count": 1
  },
  "shipping": {
    "standard_fee": "4.99",
    "express_fee": "12.50",
    "free_threshold": "100.00",
    "carriers": ["local_post", "express_courier"]
  },
  "notifications": {
    "sender_name": "Example Shop",
    "sender_address": "receipts@example.com",
    "receipt_template": "receipt-v3",
    "shipping_template": "shipping-v2",
    "refund_template": "refund-v1"
  },
  "health_checks": {
    "liveness_path": "/health/live",
    "readiness_path": "/health/ready",
    "interval_seconds": 10,
    "unhealthy_threshold": 3
  }
}
